def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    urgent_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 120 and opp.get('budget', 0) >= 300:
                    rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    danger = 0
    if hp <= 2:
        danger += 4
    elif hp <= 4:
        danger += 2
    if no_water_days >= 2:
        danger += 4
    elif no_water_days >= 1:
        danger += 2
    if tight_supply:
        danger += 2
    elif loose_supply:
        danger -= 1
    if urgent_opponents >= 2:
        danger += 1

    if danger >= 7:
        bid = max(78.0, highest_prev + 2.0)
    elif danger >= 5:
        bid = max(58.0, min(92.0, avg_prev * 0.55 + 8.0))
    elif danger >= 3:
        if rich_aggressive >= 1 and highest_prev >= 120:
            bid = 22.0 if loose_supply else 31.0
        else:
            bid = max(28.0, min(52.0, avg_prev * 0.45 + 6.0))
    else:
        if rich_aggressive >= 1 or highest_prev >= 110:
            bid = 12.0 if loose_supply else 18.0
        else:
            bid = 20.0 if not tight_supply else 26.0

    if day >= 8:
        bid += 6.0
    if hp <= 3:
        bid += 8.0
    if no_water_days >= 2:
        bid += 10.0

    reserve = 0.0
    if day <= 7:
        reserve = 35.0
    elif day <= 9:
        reserve = 15.0

    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        affordable = budget

    bid = min(bid, affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if bool(o.get('alive', False)):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate aggressiveness from yesterday
    if prev_bids:
        max_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        max_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: when supply is high, water is easier to secure; bid less.
    # When supply is low, water is scarce; bid more.
    # Map supply in [15,25] to scarcity in [1.0,0.0]
    if MAX_SUPPLY <= MIN_SUPPLY:
        scarcity = 0.5
    else:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # If our hp is low or we've already missed water, we must secure water.
    critical = (my_hp <= 2.5) or (my_no_water_days >= 1)

    # Target bid band: Cindy/Eric were ~132-145; try to undercut slightly while still winning.
    # If supply is scarce or we're critical, approach the top band.
    base = DAILY_SALARY * (0.35 + 0.35 * scarcity)  # ~31.5 to 63

    if critical:
        base = DAILY_SALARY * (0.75 + 0.15 * scarcity)  # ~67.5 to 90

    # Use yesterday's max bid as an upper reference; don't always match it.
    # If max_prev_bid is high, we increase our bid to compete.
    if max_prev_bid > 120.0:
        comp = 0.85 * max_prev_bid
    elif max_prev_bid > 80.0:
        comp = 0.75 * max_prev_bid
    else:
        comp = 0.0

    # Combine: choose the higher of base and a fraction of yesterday's max, but cap.
    bid_target = max(base, comp)

    # Slight day-based adjustment to avoid ties late: bid a bit higher on later days.
    # Keep it small.
    bid_target *= (1.0 + 0.01 * max(0, day - 1))

    # Cap by what we can pay and keep within reasonable range.
    bid = max(0.0, min(my_budget, bid_target))

    # Ensure we bid at least a minimal amount if we can; otherwise 0.
    if my_budget <= 0.0:
        return 0.0
    if bid < 1.0 and my_budget >= 1.0:
        bid = 1.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    my_hp = my_status['hp']
    my_budget = my_status['budget']

    # Find desperate opponents (low HP)
    desperate = [o for o in opponents_status.values() if o['alive'] and o['hp'] <= 2]
    high_prev_bidders = []
    for opp in opponents_status.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid', 0) is not None:
            if prev['bid'] >= DAILY_SALARY * 0.85:
                high_prev_bidders.append(prev['bid'])

    # Determine base bid
    base_bid = DAILY_SALARY * 0.5

    # Adjust for desperation
    if desperate:
        # Desperate opponents will bid high, so we need to bid higher to outbid if we need water
        if my_hp <= 2:
            base_bid = min(my_budget, DAILY_SALARY * 0.95)
        else:
            # If we are healthy, let them fight, bid low
            base_bid = DAILY_SALARY * 0.3
    elif high_prev_bidders:
        max_prev = max(high_prev_bidders)
        # Opponents likely to continue high, mimic if necessary
        if my_hp <= 2:
            base_bid = min(my_budget, max(DAILY_SALARY * 0.7, max_prev + 1))
        else:
            base_bid = min(my_budget, max(DAILY_SALARY * 0.4, max_prev - 5))
    else:
        # No extreme signals, base on hp
        if my_hp <= 2:
            base_bid = min(my_budget, DAILY_SALARY * 0.9)
        elif my_hp <= 5:
            base_bid = min(my_budget, DAILY_SALARY * 0.65)
        else:
            base_bid = min(my_budget, DAILY_SALARY * 0.4)

    # Ensure bid is not negative
    bid = max(0, base_bid)
    return bid
